package com.bank.pool;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import javax.sql.DataSource;

// Builds a HikariCP pool programmatically (Spring Boot usually does this for you).
public class PoolFactory {
    public static DataSource create(String jdbcUrl, String user, String password) {
        HikariConfig config = new HikariConfig();
        config.setJdbcUrl(jdbcUrl);
        config.setUsername(user);
        config.setPassword(password);
        config.setMaximumPoolSize(10);        // hard cap on open connections
        config.setMinimumIdle(2);             // keep a couple warm
        config.setConnectionTimeout(3000);    // borrower waits max 3s
        config.setMaxLifetime(1_800_000);     // retire connections after 30 min
        config.setLeakDetectionThreshold(20_000); // warn if held > 20s (leak)
        config.setPoolName("bank-ledger-pool");
        return new HikariDataSource(config);
    }
}
