package com.bank.pool;

import javax.sql.DataSource;
import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.logging.Logger;

public class BalanceService {
    private static final Logger log = Logger.getLogger(BalanceService.class.getName());
    private final DataSource dataSource;

    public BalanceService(DataSource dataSource) { this.dataSource = dataSource; }

    public BigDecimal getBalance(String accountId) {
        // try-with-resources: close() RETURNS the connection to the pool, not destroys it.
        try (Connection conn = dataSource.getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT balance FROM accounts WHERE id = ?")) {
            ps.setString(1, accountId);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    BigDecimal balance = rs.getBigDecimal("balance");
                    log.info(() -> "Balance for " + accountId + " = Rs." + balance);
                    return balance;
                }
                return BigDecimal.ZERO;
            }
        } catch (Exception e) {
            log.severe("Balance check failed for " + accountId + ": " + e.getMessage());
            throw new RuntimeException(e);
        }
    }
}
