package com.bank.pool;

import javax.sql.DataSource;
import java.util.logging.Logger;

public class PoolDemo {
    private static final Logger log = Logger.getLogger(PoolDemo.class.getName());

    public static void main(String[] args) {
        DataSource ds = PoolFactory.create(
            "jdbc:postgresql://localhost:5432/bankdb", "bank_app", "secret");
        BalanceService service = new BalanceService(ds);

        // Each call borrows a warm connection and returns it — no reopen cost.
        for (int i = 0; i < 5; i++) {
            service.getBalance("SAV2001");
            service.getBalance("CUR3001");
        }
        log.info("All checks reused pooled connections (max 10 ever opened).");
    }
}
